func (t *AndExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*AndExpression)
	if c := t.Arg1.CompareTo(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareTo(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *AndExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*AndExpression)
	if c := t.Arg1.CompareToLPO(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareToLPO(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of And.
func (t *AndExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("And", 2, false), t.Arg1.ToATerm(), t.Arg2.ToATerm())
}

// fromTermAndExpression is Java Gom's And.fromTerm: an unquoted application of
// And whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermAndExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "And" && !appl.GetAFun().IsQuoted() {
		return MakeAnd(ExpressionFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

// OrExpression is the term type for the alternative `Or(...)` of sort Expression.
type OrExpression struct {
	Arg1 Expression
	Arg2 Expression
	hash uint32
}

func (*OrExpression) isExpression() {}

func (t *OrExpression) Hash() uint32 { return t.hash }

func (t *OrExpression) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*OrExpression)
	if !ok {
		return false
	}
	if t.Arg1 != o.Arg1 {
		return false
	}
	if t.Arg2 != o.Arg2 {
		return false
	}
	return true
}

func (t *OrExpression) Duplicate() sharedobjects.Term {
	clone := *t
	return &clone
}

func (t *OrExpression) String() string {
	return "Or(" + fmt.Sprint(t.Arg1) + "," + fmt.Sprint(t.Arg2) + ")"
}

func (t *OrExpression) ChildCount() int { return 2 }

func (t *OrExpression) ChildAt(i int) any {
	switch i {
	case 0:
		return t.Arg1
	case 1:
		return t.Arg2
	}
	panic(fmt.Sprintf("OrExpression.ChildAt: index %d out of range", i))
}

func (t *OrExpression) SetChildAt(i int, child any) any {
	switch i {
	case 0:
		return MakeOr(child.(Expression), t.Arg2)
	case 1:
		return MakeOr(t.Arg1, child.(Expression))
	}
	panic(fmt.Sprintf("OrExpression.SetChildAt: index %d out of range", i))
}

func (t *OrExpression) Children() []any {
	return []any{t.Arg1, t.Arg2}
}

func (t *OrExpression) SetChildren(children []any) any {
	return MakeOr(children[0].(Expression), children[1].(Expression))
}

// MakeOr builds the canonical (shared) Or term.
func MakeOr(arg1 Expression, arg2 Expression) Expression {
	hashes := []uint32{arg1.Hash(), arg2.Hash()}
	proto := &OrExpression{hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Or"), hashes), Arg1: arg1, Arg2: arg2}
	return factory.Build(proto).(*OrExpression)
}

