func (t *OrExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*OrExpression)
	if c := t.Arg1.CompareTo(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareTo(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *OrExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*OrExpression)
	if c := t.Arg1.CompareToLPO(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareToLPO(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

