func (t *OrExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("Or", 2, false), t.Arg1.ToATerm(), t.Arg2.ToATerm())
}

// fromTermOrExpression is Java Gom's Or.fromTerm: an unquoted application of
// Or whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermOrExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Or" && !appl.GetAFun().IsQuoted() {
		return MakeOr(ExpressionFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

// OrExpressionDisjunctionExpression is the term type of the variadic operator `OrExpressionDisjunction(...)` of sort Expression
// (Java's abstract class OrExpressionDisjunction): a maximally-shared cons cell (Java's
// ConsOrExpressionDisjunction: a head and a tail) or the empty list (Java's EmptyOrExpressionDisjunction).
type OrExpressionDisjunctionExpression struct {
	head  Expression
	tail  Expression
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*OrExpressionDisjunctionExpression) isExpression() {}

func (t *OrExpressionDisjunctionExpression) Hash() uint32 { return t.hash }

func (t *OrExpressionDisjunctionExpression) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*OrExpressionDisjunctionExpression)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *OrExpressionDisjunctionExpression) Duplicate() sharedobjects.Term {
	return &OrExpressionDisjunctionExpression{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
func (t *OrExpressionDisjunctionExpression) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *OrExpressionDisjunctionExpression) ChildCount() int { return len(t.elements()) }

func (t *OrExpressionDisjunctionExpression) ChildAt(i int) any { return t.elements()[i] }

func (t *OrExpressionDisjunctionExpression) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *OrExpressionDisjunctionExpression) Children() []any {
	return append([]any(nil), t.elements()...)
}

// SetChildren is Java's setChildren of a list: OrExpressionDisjunctionFromArray(children).
func (t *OrExpressionDisjunctionExpression) SetChildren(children []any) any {
	args := make([]Expression, len(children))
	for i, c := range children {
		args[i] = c.(Expression)
	}
	return MakeOrExpressionDisjunction(args...)
}

func (t *OrExpressionDisjunctionExpression) String() string {
	var b strings.Builder
	b.WriteString("OrExpressionDisjunction(")
	var cur Expression = t
	for {
		c, ok := cur.(*OrExpressionDisjunctionExpression)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsOrExpressionDisjunction is Java Gom's ConsOrExpressionDisjunction.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsOrExpressionDisjunction(head Expression, tail Expression) Expression {
	proto := &OrExpressionDisjunctionExpression{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsOrExpressionDisjunction"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*OrExpressionDisjunctionExpression)
}

// realMakeEmptyOrExpressionDisjunction is Java Gom's EmptyOrExpressionDisjunction.realMake: the shared empty list,
// without hook.
func realMakeEmptyOrExpressionDisjunction() Expression {
	proto := &OrExpressionDisjunctionExpression{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyOrExpressionDisjunction"), nil)}
	return factory.Build(proto).(*OrExpressionDisjunctionExpression)
}

// RawOrExpressionDisjunction builds the OrExpressionDisjunction list holding exactly args, without construction
// hook.
func RawOrExpressionDisjunction(args ...Expression) Expression {
	l := realMakeEmptyOrExpressionDisjunction()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsOrExpressionDisjunction(args[i], l)
	}
	return l
}

// EmptyOrExpressionDisjunction is Java Gom's EmptyOrExpressionDisjunction.make(): the empty OrExpressionDisjunction list, after the
// construction hooks.
func EmptyOrExpressionDisjunction() Expression {
	return realMakeEmptyOrExpressionDisjunction()
}

// ConsOrExpressionDisjunction is Java Gom's ConsOrExpressionDisjunction.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "FL" first).
func ConsOrExpressionDisjunction(head Expression, tail Expression) Expression {
	// FL: flattened list
	if head.IsEmptyOrExpressionDisjunction() {
		return tail
	}
	if head.IsConsOrExpressionDisjunction() {
		return ConsOrExpressionDisjunction(head.GetHeadOrExpressionDisjunction(), ConsOrExpressionDisjunction(head.GetTailOrExpressionDisjunction(), tail))
	}
	if !tail.IsConsOrExpressionDisjunction() && !tail.IsEmptyOrExpressionDisjunction() {
		return ConsOrExpressionDisjunction(head, ConsOrExpressionDisjunction(tail, EmptyOrExpressionDisjunction()))
	}
	return RealMakeConsOrExpressionDisjunction(head, tail)
}

// MakeOrExpressionDisjunction builds the list of args as Tom's `OrExpressionDisjunction(args…)` does: from EmptyOrExpressionDisjunction,
// by ConsOrExpressionDisjunction, through the construction hooks (Java's OrExpressionDisjunction.fromArray).
func MakeOrExpressionDisjunction(args ...Expression) Expression {
	var l Expression = EmptyOrExpressionDisjunction()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsOrExpressionDisjunction(args[i], l)
	}
	return l
}

// OrExpressionDisjunctionFromArray is Java Gom's OrExpressionDisjunction.fromArray(array).
func OrExpressionDisjunctionFromArray(array []Expression) Expression {
	return MakeOrExpressionDisjunction(array...)
}

