// Length is Java's length(): the number of elements of the list (a
// tail that is not a OrConnector list counts as one element).
func (t *OrConnectorExpression) Length() int {
	res := 0
	var tl Expression = t
	for {
		c, ok := tl.(*OrConnectorExpression)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*OrConnectorExpression); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a OrConnector list.
func (t *OrConnectorExpression) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur Expression = t
	for {
		c, ok := cur.(*OrConnectorExpression)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*OrConnectorExpression); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsOrConnector
// (through the hooks).
func (t *OrConnectorExpression) Reverse() Expression {
	if t.empty {
		return t
	}
	var cur Expression = t
	var rev Expression = EmptyOrConnector()
	for {
		c, ok := cur.(*OrConnectorExpression)
		if !ok || c.empty {
			break
		}
		rev = ConsOrConnector(c.head, rev)
		cur = c.tail
	}
	if c, ok := cur.(*OrConnectorExpression); !ok || !c.empty {
		rev = ConsOrConnector(cur, rev)
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsOrConnector (through the hooks).
func (t *OrConnectorExpression) Append(element Expression) Expression {
	var heads []Expression
	var cur Expression = t
	for {
		c, ok := cur.(*OrConnectorExpression)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res Expression
	if c, ok := cur.(*OrConnectorExpression); ok && c.empty {
		res = ConsOrConnector(element, cur)
	} else {
		res = ConsOrConnector(cur, element)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsOrConnector(heads[i], res)
	}
	return res
}

func (t *OrConnectorExpression) CompareTo(o any) int {
	for {
		ao := o.(Expression)
		if ao == Expression(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*OrConnectorExpression)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*OrConnectorExpression)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *OrConnectorExpression) CompareToLPO(o any) int {
	for {
		ao := o.(Expression)
		if ao == Expression(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*OrConnectorExpression)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*OrConnectorExpression)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *OrConnectorExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Expression
	var cur Expression = t
	for {
		c, ok := cur.(*OrConnectorExpression)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*OrConnectorExpression); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermOrConnectorExpression is Java Gom's OrConnector.fromTerm: an application of OrConnector, or a
// list (of ToATerm), of convertible elements.
func fromTermOrConnectorExpression(trm aterm.ATerm, conv aterm.ATermConverter) (res Expression, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "OrConnector" {
		elems := make([]Expression, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = ExpressionFromTermConv(a, conv)
		}
		return MakeOrConnector(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a OrConnector (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Expression
		for !list.IsEmpty() {
			elems = append(elems, ExpressionFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeOrConnector(elems...), true
	}
	return nil, false
}

