func (t *GreaterThanExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GreaterThanExpression)
	if c := t.Arg1.CompareTo(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareTo(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *GreaterThanExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GreaterThanExpression)
	if c := t.Arg1.CompareToLPO(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareToLPO(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of GreaterThan.
func (t *GreaterThanExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("GreaterThan", 2, false), t.Arg1.ToATerm(), t.Arg2.ToATerm())
}

// fromTermGreaterThanExpression is Java Gom's GreaterThan.fromTerm: an unquoted application of
// GreaterThan whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermGreaterThanExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "GreaterThan" && !appl.GetAFun().IsQuoted() {
		return MakeGreaterThan(ExpressionFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

