func (t *GreaterOrEqualThanExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GreaterOrEqualThanExpression)
	if c := t.Arg1.CompareTo(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareTo(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *GreaterOrEqualThanExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GreaterOrEqualThanExpression)
	if c := t.Arg1.CompareToLPO(tco.Arg1); c != 0 {
		return c
	}
	if c := t.Arg2.CompareToLPO(tco.Arg2); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of GreaterOrEqualThan.
func (t *GreaterOrEqualThanExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("GreaterOrEqualThan", 2, false), t.Arg1.ToATerm(), t.Arg2.ToATerm())
}

// fromTermGreaterOrEqualThanExpression is Java Gom's GreaterOrEqualThan.fromTerm: an unquoted application of
// GreaterOrEqualThan whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermGreaterOrEqualThanExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "GreaterOrEqualThan" && !appl.GetAFun().IsQuoted() {
		return MakeGreaterOrEqualThan(ExpressionFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

