func (t *ConditionalExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("Conditional", 3, false), t.Cond.ToATerm(), t.Then.ToATerm(), t.Else.ToATerm())
}

// fromTermConditionalExpression is Java Gom's Conditional.fromTerm: an unquoted application of
// Conditional whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermConditionalExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Conditional" && !appl.GetAFun().IsQuoted() {
		return MakeConditional(ExpressionFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv), ExpressionFromTermConv(appl.GetArgument(2), conv)), true
	}
	return nil, false
}

