// MakeCast builds the canonical (shared) Cast term.
// HookMakeCast runs the user `Cast:make` hooks of the Gom module: it
// returns their result (nil if none returned) and the arguments
// they may have reassigned. The Tom mapping generated with this file
// sets it.
var HookMakeCast func(TomType, Expression) (Expression, TomType, Expression)

func MakeCast(astType TomType, source Expression) Expression {
	if HookMakeCast != nil {
		var hookResult Expression
		hookResult, astType, source = HookMakeCast(astType, source)
		if hookResult != nil {
			return hookResult
		}
	}
	hashes := []uint32{astType.Hash(), source.Hash()}
	proto := &CastExpression{hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Cast"), hashes), AstType: astType, Source: source}
	return factory.Build(proto).(*CastExpression)
}

