func (t *GetSlotExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GetSlotExpression)
	if c := t.Codomain.CompareTo(tco.Codomain); c != 0 {
		return c
	}
	if c := t.AstName.CompareTo(tco.AstName); c != 0 {
		return c
	}
	if c := strings.Compare(t.SlotNameString, tco.SlotNameString); c != 0 {
		return c
	}
	if c := t.Variable.CompareTo(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *GetSlotExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GetSlotExpression)
	if c := t.Codomain.CompareToLPO(tco.Codomain); c != 0 {
		return c
	}
	if c := t.AstName.CompareToLPO(tco.AstName); c != 0 {
		return c
	}
	if c := strings.Compare(t.SlotNameString, tco.SlotNameString); c != 0 {
		return c
	}
	if c := t.Variable.CompareToLPO(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of GetSlot.
func (t *GetSlotExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("GetSlot", 4, false), t.Codomain.ToATerm(), t.AstName.ToATerm(), aterm.MakeGomString(t.SlotNameString), t.Variable.ToATerm())
}

// fromTermGetSlotExpression is Java Gom's GetSlot.fromTerm: an unquoted application of
// GetSlot whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermGetSlotExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "GetSlot" && !appl.GetAFun().IsQuoted() {
		return MakeGetSlot(TomTypeFromTermConv(appl.GetArgument(0), conv), TomNameFromTermConv(appl.GetArgument(1), conv), aterm.GomString(appl.GetArgument(2), conv), BQTermFromTermConv(appl.GetArgument(3), conv)), true
	}
	return nil, false
}

