func (t *AddOneExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*AddOneExpression)
	if c := t.Variable.CompareTo(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *AddOneExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*AddOneExpression)
	if c := t.Variable.CompareToLPO(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of AddOne.
func (t *AddOneExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("AddOne", 1, false), t.Variable.ToATerm())
}

// fromTermAddOneExpression is Java Gom's AddOne.fromTerm: an unquoted application of
// AddOne whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermAddOneExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "AddOne" && !appl.GetAFun().IsQuoted() {
		return MakeAddOne(BQTermFromTermConv(appl.GetArgument(0), conv)), true
	}
	return nil, false
}

