func (t *GetSizeExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GetSizeExpression)
	if c := t.Opname.CompareTo(tco.Opname); c != 0 {
		return c
	}
	if c := t.Variable.CompareTo(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

