// ToATerm is the ATerm of the term: an application of GetSize.
func (t *GetSizeExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("GetSize", 2, false), t.Opname.ToATerm(), t.Variable.ToATerm())
}

// fromTermGetSizeExpression is Java Gom's GetSize.fromTerm: an unquoted application of
// GetSize whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermGetSizeExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "GetSize" && !appl.GetAFun().IsQuoted() {
		return MakeGetSize(TomNameFromTermConv(appl.GetArgument(0), conv), BQTermFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

