func (t *DoWhileExpressionExpression) CompareTo(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*DoWhileExpressionExpression)
	if c := t.EndExpression.CompareTo(tco.EndExpression); c != 0 {
		return c
	}
	if c := t.LoopCondition.CompareTo(tco.LoopCondition); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *DoWhileExpressionExpression) CompareToLPO(o any) int {
	ao := o.(Expression)
	if ao == Expression(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*DoWhileExpressionExpression)
	if c := t.EndExpression.CompareToLPO(tco.EndExpression); c != 0 {
		return c
	}
	if c := t.LoopCondition.CompareToLPO(tco.LoopCondition); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of DoWhileExpression.
func (t *DoWhileExpressionExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("DoWhileExpression", 2, false), t.EndExpression.ToATerm(), t.LoopCondition.ToATerm())
}

// fromTermDoWhileExpressionExpression is Java Gom's DoWhileExpression.fromTerm: an unquoted application of
// DoWhileExpression whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermDoWhileExpressionExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "DoWhileExpression" && !appl.GetAFun().IsQuoted() {
		return MakeDoWhileExpression(ExpressionFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

