func (t *IsSortExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("IsSort", 2, false), t.AstType.ToATerm(), t.Variable.ToATerm())
}

// fromTermIsSortExpression is Java Gom's IsSort.fromTerm: an unquoted application of
// IsSort whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermIsSortExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "IsSort" && !appl.GetAFun().IsQuoted() {
		return MakeIsSort(TomTypeFromTermConv(appl.GetArgument(0), conv), BQTermFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

// CodeExpression is the term type for the alternative `Code(...)` of sort Expression.
type CodeExpression struct {
	Code string
	hash uint32
}

