func (t *CodeExpression) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("Code", 1, false), aterm.MakeGomString(t.Code))
}

// fromTermCodeExpression is Java Gom's Code.fromTerm: an unquoted application of
// Code whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermCodeExpression(trm aterm.ATerm, conv aterm.ATermConverter) (Expression, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Code" && !appl.GetAFun().IsQuoted() {
		return MakeCode(aterm.GomString(appl.GetArgument(0), conv)), true
	}
	return nil, false
}

func init() {
	HookMakeBQTermToExpression = func(t BQTerm) (Expression, BQTerm) {
		tom__r := func() Expression {
			{

				if t.IsExpressionToBQTerm() {
					return t.GetExp()
				}

			}
			return nil
		}()
		return tom__r, t
	}
}

func init() {
	HookMakeCast = func(tp TomType, exp Expression) (Expression, TomType, Expression) {
		tom__r := func() Expression {
			{

				if tp.IsType() && tp.GetTypeOptions().IsEmptyconcTypeOption() && tp.GetTomType() == "unknown type" && tp.GetTlType().IsEmptyTargetLanguageType() {
					panic("bad cast")
				}

			}
			return nil
		}()
		return tom__r, tp, exp
	}
}
